import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CsGzzEsd.js";const g=JSON.parse('{"title":"seanpnex.github.io","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),o={name:"README.md"};function n(r,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="seanpnex-github-io" tabindex="-1">seanpnex.github.io <a class="header-anchor" href="#seanpnex-github-io" aria-label="Permalink to &quot;seanpnex.github.io&quot;">​</a></h1><p>Sean Guo&#39;s personal site and public learning base, built with <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a> and deployed to GitHub Pages at <strong><a href="https://seanpnex.github.io" target="_blank" rel="noreferrer">seanpnex.github.io</a></strong>.</p><p>It hosts research projects plus evolving study notes for CFA Level II, JLPT N2, and Business German, available in English, 简体中文, 日本語, and Français.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to &quot;What&#39;s inside&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>index.md</code></td><td>Home page</td></tr><tr><td><code>projects/</code></td><td>Research and project write-ups (NCCP, TTS chatbot, rivalry network, Wilson–Cowan equation)</td></tr><tr><td><code>blogs/</code></td><td>Learning base: <code>CFA/</code>, <code>JLPT-N2/</code>, <code>German/</code>, <code>coding_notes/</code></td></tr><tr><td><code>zh/</code>, <code>jp/</code>, <code>fr/</code></td><td>Translated pages, mirroring the English layout</td></tr><tr><td><code>public/charts/</code></td><td>Standalone interactive HTML charts embedded in notes via <code>&lt;iframe&gt;</code></td></tr><tr><td><code>public/flashcards/</code></td><td>Standalone flashcard decks built from CFA quizzes</td></tr><tr><td><code>public/</code></td><td>PDFs, images, and other static assets served as-is</td></tr><tr><td><code>.vitepress/</code></td><td>Site config, auto-generated sidebar, and custom theme</td></tr></tbody></table><h2 id="run-locally" tabindex="-1">Run locally <a class="header-anchor" href="#run-locally" aria-label="Permalink to &quot;Run locally&quot;">​</a></h2><p>Requires Node.js 18+ (CI uses Node 20).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> install</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> run</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> docs:dev</span></span></code></pre></div><p>The dev server runs at <code>localhost:5173</code>. To check a production build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> run</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> docs:build</span><span style="--shiki-light:#212121;--shiki-dark:#BBBBBB;"> &amp;&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> run</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> docs:preview</span></span></code></pre></div><h2 id="writing-notes" tabindex="-1">Writing notes <a class="header-anchor" href="#writing-notes" aria-label="Permalink to &quot;Writing notes&quot;">​</a></h2><p>The sidebar is generated from the folder tree by <a href=".vitepress/auto-sidebar.mjs"><code>.vitepress/auto-sidebar.mjs</code></a>, so adding a note is just adding a Markdown file.</p><ul><li><strong>Ordering</strong> — files and folders sort by name; a prefix like <code>C2 </code> or <code>M1 </code> sets the order and is stripped from the label. Set <code>order:</code> in frontmatter to override.</li><li><strong>Labels</strong> — <code>title:</code> in frontmatter sets the sidebar text. Curriculum folder names map to readable labels via <code>GROUP_LABELS</code> in <code>auto-sidebar.mjs</code> (translations live in <code>topics.mjs</code>).</li><li><strong>Publishing</strong> — empty notes and notes with <code>draft: true</code> stay in the repo but are excluded from the build. Short notes (under ~1,500 characters) are published as outlines.</li><li><strong>Prev / next</strong> — page sequence follows the sidebar, and each learning track has its own sidebar so navigation stays inside the track.</li><li><strong>Math and diagrams</strong> — LaTeX math (<code>$…$</code>, <code>$$…$$</code>) and <code>```mermaid</code> blocks are supported.</li></ul><h3 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h3><p>Charts in <code>public/charts/</code> are self-contained HTML pages. Notes embed them with an iframe, adding <code>?lang=zh|ja|fr</code> for translated pages; each chart registers its own strings with <a href="public/charts/i18n.js"><code>i18n.js</code></a>. Charts report their rendered height to the host page, so the iframe resizes itself. The hairline curve charts share drawing helpers in <a href="public/charts/curve-kit.js"><code>curve-kit.js</code></a>.</p><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h2><p>Locales are configured in <a href=".vitepress/config.mjs"><code>.vitepress/config.mjs</code></a> (<code>LOCALE_TEXT</code> holds the interface strings). Translated pages live under <code>/zh/</code>, <code>/jp/</code>, and <code>/fr/</code>. Learning notes are written in English first; when the language menu points to a translation that doesn&#39;t exist yet, it opens the English page instead of a 404.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>Pushing to <code>main</code> triggers <a href=".github/workflows/deploy.yml"><code>.github/workflows/deploy.yml</code></a>, which builds the site and publishes <code>.vitepress/dist</code> to the <code>gh-pages</code> branch. A second workflow, <a href=".github/workflows/commit_log.yml"><code>commit_log.yml</code></a>, appends each push to <code>workflow.log</code> and commits it back, so pull before pushing.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p><a href="https://github.com/SEANPNEX/seanpnex.github.io/blob/main/LICENSE" target="_blank" rel="noreferrer">GPL-3.0</a></p>',22)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
